<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Berita Acara Draf · <?= h($row['ticket_no']) ?></title><style>body{font:15px/1.55 Georgia,serif;color:#182a24;max-width:820px;margin:35px auto;padding:0 24px}.head{display:flex;gap:18px;align-items:center;border-bottom:3px double #333;padding-bottom:15px}.head img{width:54px;height:72px;object-fit:contain}.head h1{font-size:19px;margin:0}.head p{margin:0}.draft{border:1px solid #a35f48;color:#a35f48;padding:8px 12px;display:inline-block;margin:25px 0 10px;font:700 12px Arial}h2{text-align:center;font-size:18px;text-transform:uppercase}table{width:100%;border-collapse:collapse;margin:18px 0}td,th{border:1px solid #555;padding:9px;vertical-align:top}th{width:170px;text-align:left;background:#f4f4f1}.event{border-bottom:1px solid #ddd;padding:12px 0}.sign{margin-top:55px;display:flex;justify-content:space-between}.sign div{width:42%;text-align:center}.sign span{display:block;margin-top:65px}button{margin:20px 0;padding:9px 15px}@media print{button{display:none}body{margin:0}}</style></head><body><?php $site=site_profile(); ?><button onclick="window.print()">Cetak draf</button><div class="head"><img src="<?= base_url($site['logo_path']) ?>" alt="Lambang Kabupaten Rembang"><div><h1><?= h(mb_strtoupper($site['government_name'])) ?></h1><p><?= h($site['opd_name']) ?> · <?= h($site['division_name']) ?></p></div></div><span class="draft">DRAF · BELUM DITANDATANGANI / BELUM BERNOMOR RESMI</span><h2>Berita Acara Penanganan <?= $slug==='aduan'?'Aduan':'Layanan' ?></h2><table><tr><th>Nomor tiket</th><td><?= h($row['ticket_no']) ?></td></tr><tr><th>Perihal</th><td><?= h($row['title']) ?></td></tr><tr><th>Koperasi</th><td><?= h($row['cooperative_name']?:'—') ?></td></tr><tr><th>Pemohon</th><td><?= h($row['reporter_name']?:'—') ?></td></tr><tr><th>Diterima</th><td><?= h(date('d M Y H:i',strtotime($row['created_at']))) ?></td></tr><tr><th>Status terakhir</th><td><?= h($row['status']) ?></td></tr></table><h3>Uraian</h3><p><?= nl2br(h($row['description'])) ?></p><h3>Kronologi dan tindak lanjut</h3><?php foreach ($events as $e): ?><div class="event"><strong><?= h(date('d M Y H:i',strtotime($e['created_at']))) ?> · <?= h($e['actor_name']?:'Sistem') ?></strong><br><?= nl2br(h($e['note'])) ?></div><?php endforeach; ?><div class="sign"><div>Petugas pencatat<span>(....................................)</span></div><div>Pihak terkait<span>(....................................)</span></div></div><p><small>Dokumen ini dihasilkan sebagai draf kerja dari tiket. Pengesahan dan nomor naskah mengikuti tata naskah dinas.</small></p></body></html>
